import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/chicken-rabbit-logic.svg",g=JSON.parse('{"title":"奥数精讲：鸡兔同笼问题初步（假设法的魅力）","description":"探索中国古代数学名题“鸡兔同笼”，掌握最核心的“假设法”解题逻辑，通过生动的图示让抽象的脚数计算变得直观易懂。","frontmatter":{"title":"奥数精讲：鸡兔同笼问题初步（假设法的魅力）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["鸡兔同笼","假设法","逻辑推理"],"description":"探索中国古代数学名题“鸡兔同笼”，掌握最核心的“假设法”解题逻辑，通过生动的图示让抽象的脚数计算变得直观易懂。"},"headers":[],"relativePath":"posts/primary-math-olympiad-chicken-rabbit-intro.md","filePath":"posts/primary-math-olympiad-chicken-rabbit-intro.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-chicken-rabbit-intro.md"};function o(r,a,e,c,i,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="鸡兔同笼-穿越千年的数学智慧" tabindex="-1">鸡兔同笼：穿越千年的数学智慧 <a class="header-anchor" href="#鸡兔同笼-穿越千年的数学智慧" aria-label="Permalink to &quot;鸡兔同笼：穿越千年的数学智慧&quot;">​</a></h1><p>“今有雉兔同笼，上有三十五头，下有九十四足，问雉兔各几何？” 这是《孙子算经》中记载的著名题目。这类问题在奥数中被称为<strong>鸡兔同笼问题</strong>。解决它的精髓在于——<strong>大胆假设，小心调整</strong>。</p><hr><h2 id="一、-核心解题策略-假设法" tabindex="-1">一、 核心解题策略：假设法 <a class="header-anchor" href="#一、-核心解题策略-假设法" aria-label="Permalink to &quot;一、 核心解题策略：假设法&quot;">​</a></h2><p>假设法是解决鸡兔同笼最通用、最直观的方法。</p><h3 id="【示例-1】" tabindex="-1">【示例 1】 <a class="header-anchor" href="#【示例-1】" aria-label="Permalink to &quot;【示例 1】&quot;">​</a></h3><p><strong>题目：</strong> 笼子里有 8 个头，22 只脚。求鸡和兔各几只？</p><p><img src="'+p+'" alt="鸡兔同笼假设法图解"></p><p><strong>解题步骤：</strong></p><ol><li><strong>大胆假设：</strong> 假设笼子里全是鸡。 <ul><li>那么脚应该有：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">8 \\times 2 = 16</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span></span></span></span> 只。</li></ul></li><li><strong>比较差距：</strong> 题目说有 22 只脚，我们算出来只有 16 只。 <ul><li>差距是：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>2</mn><mo>−</mo><mn>1</mn><mn>6</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">22 - 16 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span> 只。</li></ul></li><li><strong>寻找原因：</strong> 为什么会少 6 只脚？ <ul><li>因为我们把 4 条腿的兔子当成了 2 条腿的鸡。</li><li>每把一只“假鸡”换回“真兔”，脚数就会增加 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">4 - 2 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 只。</li></ul></li><li><strong>得出结论：</strong><ul><li>兔子的只数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">6 \\div 2 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span> 只。</li><li>鸡的只数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">8 - 3 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 只。 <strong>验证：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>2</mn><mo>+</mo><mn>3</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>2</mn><mo>=</mo><mn>2</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">5 \\times 2 + 3 \\times 4 = 10 + 12 = 22</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">2</span></span></span></span>。完全正确！</li></ul></li></ol><hr><h2 id="二、-引导性思考-如果假设全是兔呢" tabindex="-1">二、 引导性思考：如果假设全是兔呢？ <a class="header-anchor" href="#二、-引导性思考-如果假设全是兔呢" aria-label="Permalink to &quot;二、 引导性思考：如果假设全是兔呢？&quot;">​</a></h2><p>如果我们换个思路，假设全是兔：</p><ol><li><strong>计算脚数：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">8 \\times 4 = 32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span> 只。</li><li><strong>比较差距：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>2</mn><mo>−</mo><mn>2</mn><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">32 - 22 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 只（多算了）。</li><li><strong>调整：</strong> 每把一只兔换成鸡，脚数减少 2 只。</li><li><strong>结论：</strong> 鸡的只数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">= 10 \\div 2 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 只。</li></ol><p><strong>引导思考：</strong> 无论假设全是鸡还是全是兔，都能算出答案。通常我们假设脚数少的那种动物（鸡），算出来的结果就是另一种动物（兔）。</p><hr><h2 id="三、-引申思考-生活中的-鸡兔同笼" tabindex="-1">三、 引申思考：生活中的“鸡兔同笼” <a class="header-anchor" href="#三、-引申思考-生活中的-鸡兔同笼" aria-label="Permalink to &quot;三、 引申思考：生活中的“鸡兔同笼”&quot;">​</a></h2><p>鸡兔同笼不一定真的在数鸡和兔，它是一种<strong>模型</strong>。只要满足“两个对象、两种标准、一个总量”的问题，都可以用它。</p><ul><li><strong>租船问题：</strong> 大船坐 6 人，小船坐 4 人，共 10 条船坐了 52 人。</li><li><strong>硬币问题：</strong> 5 角硬币和 1 元硬币共 20 枚，总面值 16 元。</li><li><strong>得分问题：</strong> 答对一题得 5 分，答错一题扣 2 分。</li></ul><hr><h2 id="四、-举一反三-实战练习" tabindex="-1">四、 举一反三：实战练习 <a class="header-anchor" href="#四、-举一反三-实战练习" aria-label="Permalink to &quot;四、 举一反三：实战练习&quot;">​</a></h2><ol><li><p><strong>基础练习：</strong> 鸡兔同笼，共有 10 个头，28 只脚。求鸡和兔各多少只？ <em>提示：假设全是鸡，少了多少只脚？</em></p></li><li><p><strong>进阶练习（租船）：</strong> 同学们去划船，大船坐 5 人，小船坐 3 人。一共租了 12 条船，刚好坐了 46 人。大船和小船各租了几条？ <em>提示：假设全是小船，能坐多少人？还差多少人？</em></p></li><li><p><strong>挑战练习（得分）：</strong> 一次数学竞赛共 20 题。做对一题得 5 分，做错或没做扣 3 分。小明得了 60 分，他做对了几道题？ <em>提示：假设全做对，应得 100 分。少得 40 分是因为错一题不仅没拿到 5 分，还要扣 3 分，差距是 8 分。</em></p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li>兔：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>8</mn><mo>−</mo><mn>1</mn><mn>0</mn><mo>×</mo><mn>2</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">(28 - 10 \\times 2) \\div 2 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">8</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 只；鸡：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">10 - 4 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span> 只。</li><li>大船：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>4</mn><mn>6</mn><mo>−</mo><mn>1</mn><mn>2</mn><mo>×</mo><mn>3</mn><mo>)</mo><mo>÷</mo><mo>(</mo><mn>5</mn><mo>−</mo><mn>3</mn><mo>)</mo><mo>=</mo><mn>1</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">(46 - 12 \\times 3) \\div (5 - 3) = 10 \\div 2 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 条；小船：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">12 - 5 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span> 条。</li><li>错题：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>6</mn><mn>0</mn><mo>)</mo><mo>÷</mo><mo>(</mo><mn>5</mn><mo>+</mo><mn>3</mn><mo>)</mo><mo>=</mo><mn>4</mn><mn>0</mn><mo>÷</mo><mn>8</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">(100 - 60) \\div (5 + 3) = 40 \\div 8 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 道；对题：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">20 - 5 = 15</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span> 道。 (验证：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>×</mo><mn>5</mn><mo>−</mo><mn>5</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>7</mn><mn>5</mn><mo>−</mo><mn>1</mn><mn>5</mn><mo>=</mo><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">15 \\times 5 - 5 \\times 3 = 75 - 15 = 60</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">7</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span>。正确！)</li></ol>',25)])])}const x=s(l,[["render",o]]);export{g as __pageData,x as default};
